import {
  Controller,
  Post,
  Get,
  Body,
  Query,
  UseGuards,
  Request,
  HttpCode,
  NotFoundException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
import { Throttle } from '@nestjs/throttler';
import { BypassableThrottlerGuard as ThrottlerGuard } from '../common/guards/throttler-bypass.guard';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { IpnsService } from './ipns.service';
import {
  PublishIpnsDto,
  PublishIpnsResponseDto,
  BatchPublishIpnsDto,
  BatchPublishIpnsResponseDto,
  ResolveIpnsQueryDto,
  ResolveIpnsResponseDto,
  BatchUnenrollIpnsDto,
  BatchUnenrollIpnsResponseDto,
  TombstoneIpnsDto,
} from './dto';
import { MetricsService } from '../metrics/metrics.service';
import { RequestWithUser } from '../common/types';

@ApiTags('IPNS')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('ipns')
export class IpnsController {
  constructor(
    private readonly ipnsService: IpnsService,
    private readonly metricsService: MetricsService
  ) {}

  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
  // Each publish makes external HTTP calls to the delegated routing service
  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
  @Post('publish')
  @ApiOperation({
    summary: 'Publish IPNS record',
    description:
      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
      'The client signs the record locally; backend relays to the delegated routing service and tracks ' +
      'the folder for TEE republishing.',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS record published successfully',
    type: PublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or missing required fields',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - expectedSequenceNumber does not match current server sequence number. ' +
      'Response body includes currentSequenceNumber for client re-sync.',
  })
  @ApiResponse({
    status: 410,
    description: 'Gone - IPNS name has been tombstoned (rotated out; no longer publishable)',
    schema: {
      type: 'object',
      properties: {
        error: { type: 'string', example: 'IPNS_TOMBSTONED' },
        ipnsName: { type: 'string' },
      },
    },
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to publish to delegated routing',
  })
  async publishRecord(
    @Request() req: RequestWithUser,
    @Body() dto: PublishIpnsDto
  ): Promise<PublishIpnsResponseDto> {
    const result = await this.ipnsService.publishRecord(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'single' });
    return result;
  }

  // [SECURITY: HIGH-04] Rate limit batch publish - lower limit since each batch can have up to 200 records
  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch publishes per minute per user
  @Post('publish-batch')
  @ApiOperation({
    summary: 'Batch publish IPNS records',
    description:
      'Publish multiple IPNS records (folder and/or file) in a single API call. ' +
      'Supports up to 200 records per batch with concurrency-limited processing. ' +
      'Partial success is allowed: individual record failures do not fail the batch.',
  })
  @ApiResponse({
    status: 200,
    description: 'Batch publish results with per-record outcomes',
    type: BatchPublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or batch exceeds 200 entries',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - a folder record in the batch has an expectedSequenceNumber that does not match ' +
      'the current server sequence number. The entire batch is rejected.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Delegated routing failures (partial results may be returned)',
  })
  async publishBatch(
    @Request() req: RequestWithUser,
    @Body() dto: BatchPublishIpnsDto
  ): Promise<BatchPublishIpnsResponseDto> {
    const result = await this.ipnsService.publishBatch(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'batch' }, result.totalSucceeded);
    return result;
  }

  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch unenrolls per minute per user
  @Post('unenroll')
  @HttpCode(200)
  @ApiOperation({
    summary: 'Batch unenroll IPNS records from TEE republishing',
    description:
      'Remove IPNS names from the TEE republish schedule. Called after file/folder deletion ' +
      'to prevent orphaned records from accumulating. Accepts up to 200 IPNS names per call.',
  })
  @ApiResponse({
    status: 200,
    description: 'Unenrollment results',
    type: BatchUnenrollIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid IPNS name format or array too large',
  })
  @ApiResponse({ status: 401, description: 'Unauthorized - JWT token required' })
  async unenrollBatch(
    @Request() req: RequestWithUser,
    @Body() dto: BatchUnenrollIpnsDto
  ): Promise<BatchUnenrollIpnsResponseDto> {
    const result = await this.ipnsService.unenrollBatch(req.user.id, dto.ipnsNames);
    return {
      totalUnenrolled: result.totalUnenrolled,
      totalRequested: dto.ipnsNames.length,
    };
  }

  // [SECURITY: HIGH-04] Rate limit IPNS resolve - higher limit than publish since read-only
  @Throttle({ default: { limit: 30, ttl: 60000 } }) // 30 resolves per minute per user
  @Get('resolve')
  @ApiOperation({
    summary: 'Resolve IPNS name',
    description:
      'Resolve an IPNS name to its current CID via delegated routing. ' +
      'Returns the CID and sequence number of the current IPNS record.',
  })
  @ApiQuery({
    name: 'ipnsName',
    description:
      'IPNS name to resolve. Supports CIDv1 IPNS names starting with "k51..." (PeerID-style) or "bafzaa..." (IPNS key CID).',
    example: 'REDACTED',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS name resolved successfully',
    type: ResolveIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid IPNS name format',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 404,
    description: 'Not Found - IPNS name not published or not found in routing network',
  })
  @ApiResponse({
    status: 410,
    description: 'Gone - IPNS name has been tombstoned (rotated out; name is permanently retired)',
    schema: {
      type: 'object',
      properties: {
        error: { type: 'string', example: 'IPNS_TOMBSTONED' },
        ipnsName: { type: 'string' },
      },
    },
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to resolve from delegated routing',
  })
  async resolveRecord(@Query() query: ResolveIpnsQueryDto): Promise<ResolveIpnsResponseDto> {
    const result = await this.ipnsService.resolveRecord(query.ipnsName);

    if (!result) {
      throw new NotFoundException('IPNS name not found in routing network');
    }

    // Track resolve source: if signatureV2 is present, it came from the network
    const source = result.signatureV2 ? 'network' : 'db_cache';
    this.metricsService.ipnsResolves.inc({ source });

    // Include signature fields as all-or-nothing bundle for client verification
    const hasSigData = result.signatureV2 && result.data && result.pubKey;
    return {
      success: true,
      cid: result.cid,
      sequenceNumber: result.sequenceNumber,
      ...(hasSigData && {
        signatureV2: result.signatureV2,
        data: result.data,
        pubKey: result.pubKey,
      }),
    };
  }

  @Post('tombstone')
  @HttpCode(200)
  @ApiOperation({
    summary: 'Tombstone an IPNS record',
    description:
      'Permanently retire an IPNS name owned by the caller. ' +
      'Sets tombstoned_at and removes the name from the TEE republish schedule. ' +
      'Subsequent publish and resolve calls for this name return HTTP 410 Gone.',
  })
  @ApiResponse({ status: 200, description: 'Record tombstoned and unenrolled from republishing' })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid IPNS name format',
  })
  @ApiResponse({ status: 401, description: 'Unauthorized - JWT token required' })
  async tombstoneRecord(
    @Request() req: RequestWithUser,
    @Body() dto: TombstoneIpnsDto
  ): Promise<void> {
    await this.ipnsService.tombstoneRecord(req.user.id, dto.ipnsName);
  }
}

