export const meta = {
  name: 'restore-api-controller-coverage',
  description: 'Author jest specs to restore API coverage the Phase 66 cutover deleted',
  phases: [{ title: 'Author specs', detail: 'one agent per uncovered surface, scoped coverage verify' }],
}

const REPO = '/Users/myankelev/Code/random/cipher-box'
const API = `${REPO}/apps/api`

const TARGETS = [
  {
    src: 'src/shares/shares.controller.ts',
    spec: 'src/shares/shares.controller.spec.ts',
    threshold: 'lines >= 80, branches >= 65',
    note: 'Descriptor-ref shares controller. Mock SharesService. Cover happy paths + auth (req.user.id) + error/guard branches.',
  },
  {
    src: 'src/shares/share-invites.controller.ts',
    spec: 'src/shares/share-invites.controller.spec.ts',
    threshold: 'lines >= 80, branches >= 65',
    note: 'Invite listing/management controller. Mock ShareInviteService. Cover all handlers + branches.',
  },
  {
    src: 'src/shares/invites.controller.ts',
    spec: 'src/shares/invites.controller.spec.ts',
    threshold: 'lines >= 80, branches >= 74',
    note: 'Invite create/claim/status controller. Mock ShareInviteService. Cover all handlers + branches (74% branches needed — be thorough on conditionals).',
  },
  {
    src: 'src/ipns/ipns.controller.ts',
    spec: 'src/ipns/ipns.controller.spec.ts',
    threshold: 'functions >= 60 (currently 50). lines>=73 and branches>=70 already pass — keep them passing.',
    note: 'No ipns.controller.spec exists yet. Mock IpnsService. Cover EVERY controller handler (publish, publish-batch, unenroll, resolve, tombstone) so functions coverage clears 60%. The tombstone handler is brand new — definitely cover it.',
  },
  {
    src: 'src/shares/shares.service.ts',
    spec: 'src/shares/shares.service.ts'.replace('.ts', '.spec.ts'),
    threshold: 'no per-file gate, but aim lines >= 80 / branches >= 65 to lift GLOBAL branches above 78%',
    note: 'Descriptor-ref SharesService: grant creation, revokeShare hard-delete, received/sent listing, hidden-by-recipient. Mock the TypeORM repositories. This is the biggest 0%-covered file — strong coverage here is what lifts the global branch threshold.',
  },
]

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['specPath', 'meetsThreshold', 'lines', 'branches', 'functions', 'testCount', 'summary'],
  properties: {
    specPath: { type: 'string' },
    meetsThreshold: { type: 'boolean', description: 'true if the scoped coverage meets the stated threshold' },
    lines: { type: 'number' },
    branches: { type: 'number' },
    functions: { type: 'number' },
    testCount: { type: 'number' },
    summary: { type: 'string', description: 'one line: what was covered + final coverage numbers' },
  },
}

function prompt(t) {
  return `You are authoring a Jest unit spec for a NestJS file in the CipherBox API to restore code coverage that a refactor deleted. Work entirely inside ${API}.

TARGET FILE: ${t.src}
SPEC TO CREATE: ${t.spec}
COVERAGE THRESHOLD TO MEET: ${t.threshold}
CONTEXT: ${t.note}

Steps:
1. Read the target file ${API}/${t.src} in full to learn its exact methods, dependencies (constructor injection), DTOs, and branches.
2. Read an exemplar spec for the mocking pattern: ${API}/src/vault/vault.controller.spec.ts (controllers) or ${API}/src/republish/republish.service.spec.ts (services). Match their NestJS Test.createTestingModule + getRepositoryToken / mocked-provider style.
3. Read whatever DTOs / entities / service interfaces the target imports so your mocks match real signatures.
4. Write ${API}/${t.spec} with MEANINGFUL tests — happy path, auth/ownership (req.user.id), and error/guard branches. Do NOT write coverage-padding assertions; each test must assert real behavior. Use string literals over enums. No \`any\` if avoidable (CI lints \`@typescript-eslint/no-explicit-any\` as a warning; prefer typed mocks).
5. Verify with a SCOPED coverage run ONLY — never the full suite (RAM):
     cd ${API} && npx jest ${t.spec} --coverage --collectCoverageFrom='${t.src}' --coverageThreshold='{}'
   Read the coverage table row for ${t.src}. Iterate (edit the spec, re-run) until it clears the threshold.
6. Make sure the spec is GREEN (all tests pass) and the file's coverage meets the threshold.

Hard constraints:
- NEVER modify the implementation file ${t.src} or any other non-spec file. Only create/edit ${t.spec}.
- Run ONLY the single scoped jest command above. NEVER run \`jest\` without a file filter, never run the full api suite, never run e2e. (RAM starvation.)
- The spec must end green and meet the threshold. If a branch is genuinely unreachable, note it and get as close as the threshold requires via other branches.
- Return the structured result: specPath, meetsThreshold, lines, branches, functions (the scoped coverage numbers for ${t.src}), testCount, and a one-line summary.`
}

const results = await parallel(
  TARGETS.map((t) => () =>
    agent(prompt(t), { label: `spec:${t.src.split('/').pop()}`, phase: 'Author specs', schema: SCHEMA })
  )
)

return results.map((r, i) => ({ target: TARGETS[i].src, ...(r || { failed: true }) }))
